const lkBills=pid=>db.sales.filter(x=>x.status==="posted"&&x.party_id===pid&&(S.unit==="all"||x.unit_id===S.unit)&&owedS(x)>0.005).sort((a,b)=>a.date.localeCompare(b.date)||a._id.localeCompare(b._id)),
 lkSel=()=>lkBills(S.lkp).filter(x=>(S.lks||{})[x._id]),lkFineOf=(x,d)=>{const f=lateFine(x,d,owedS(x));return f===null?0:Math.round(f)};
function lkPick(pid){S.lkp=pid;S.lks={};S.lkr=null;S.lkd=null;lkBills(pid).forEach(x=>{S.lks[x._id]=1});render()}
