function lkClose(){S.lkp=null;S.lks=null;S.lkr=null;S.lkd=null;render()}
function loketBayar(){try{negAny();const d=$("#lk-d").value,k=db.cash_accounts.find(c=>c._id===$("#lk-k").value),free=!!($("#lk-f0")&&$("#lk-f0").checked),L=lkSel();
 if(!L.length)throw Error("Pilih minimal satu tagihan");if(!d)throw fe("lk-d","Tanggal wajib diisi");if(!k)throw fe("lk-k","Pilih kas/bank");if(closed(d))throw fe("lk-d","Periode "+d.slice(0,7)+" sudah ditutup");
 L.forEach(x=>{if(d<x.date)throw fe("lk-d","Tanggal bayar tidak boleh sebelum tanggal tagihan "+x.sale_number)});
 const ids=[];let tot=0,fn=0;
 L.forEach(x=>{const o=owedS(x),lf=lateFine(x,d,o),f=lf===null||free?0:Math.round(lf),
  t=post({type:"sale_pay",date:d,unit:x.unit_id,desc:"Pembayaran "+x.sale_number+" – "+cust(x.party_id).name+(f>0?" + denda":""),lines:[{acc:k.account_id,d:o+f},{acc:"ACC1400",c:o}].concat(f>0?[{acc:"ACC4210",c:f}]:[])}),pid=uid("PAY");
  db.payments.push({_id:pid,sale_id:x._id,date:d,amount:o,cash_id:k._id,transaction_id:t._id,status:"posted",...byN(),...(lf!==null?{fine:f}:{})});if(lf!==null)x.fine_done={amt:f,date:d,pay:pid,auto:lf};
  audit("receive","sale",x._id,"loket"+(f>0?" · denda Rp "+fm(f):lf!==null?" · denda dibebaskan":""));ids.push(pid);tot+=o+f;fn+=f});
 save();S.lkr=ids;udSet("batalTerima",ids.slice());hlSet(...L.map(x=>x._id));S.lks={};S.lkd=null;S.msg="Pembayaran "+L.length+" tagihan diterima · Rp "+fm(tot)+(fn?" (termasuk denda Rp "+fm(fn)+")":"")+"; cetak kuitansi di bawah"}catch(e){ferr(e);return}render()}
function vLoket(){const U=x=>S.unit==="all"||x.unit_id===S.unit,by={};db.sales.filter(x=>x.status==="posted"&&x.party_id&&U(x)&&owedS(x)>0.005).forEach(x=>{const z=by[x.party_id]??={n:0,o:0};z.n++;z.o+=owedS(x)});
 const mt=pid=>db.water_connections.filter(c=>c.party_id===pid).map(c=>c.meter_no).join(" "),q=(S.wq||"").trim(),can=!noPerm("air.kelola"),
  pel=db.parties.filter(p=>p.type==="pelanggan"&&wqHit(p,mt(p._id))&&(q||by[p._id])).sort((a,b)=>((by[b._id]||{o:0}).o-(by[a._id]||{o:0}).o)||String(a.name).localeCompare(String(b.name),"id")).slice(0,8),
  cari=dcard("Cari pelanggan",q?"Hasil pencarian":"Tunggakan terbesar",wSrch("Nama / telepon / alamat / no meter…")+(pel.length?`<div class="upl">${pel.map((p,i)=>{const z=by[p._id];return`<button class="upr nsr${S.lkp===p._id?" on":""}" onclick="lkPick('${p._id}')">${avA(p.name,i)}<span class="upm"><b>${esc(p.name)}</b><small>${mt(p._id)?"Meter "+esc(mt(p._id)):esc(p.phone||"")}</small>${z?`<small class="smw">Menunggak ${z.n} tagihan · ${rp(z.o)}</small>`:`<small>Tidak ada tunggakan</small>`}</span><span class="upa">${z?'<span class="bdg wr">Belum lunas</span>':'<span class="bdg ok">Lunas</span>'}</span></button>`}).join("")}</div>`:q?wNone():wEmp("check","Tidak ada pelanggan dengan tunggakan",["Ke Baca Meter","S.at='baca';S.wq='';render()"])),"");
 let pan="";
 if(S.lkp){const p=cust(S.lkp),L=lkBills(S.lkp),d=S.lkd||today(),sel=L.filter(x=>(S.lks||{})[x._id]),fs=sel.map(x=>lkFineOf(x,d)),sO=sel.reduce((t,x)=>t+owedS(x),0),sF=fs.reduce((t,f)=>t+f,0),
   rows=L.map(x=>{const f=lkFineOf(x,d),lb=x.bill?"Air "+x.bill.period+(x.bill.est?" (taksiran)":""):(itemsNote(x)||esc(x.sale_number));return`<label class="upr alr"><input type="checkbox"${(S.lks||{})[x._id]?" checked":""} onchange="lkTog('${x._id}',this.checked)" aria-label="Pilih ${esc(lb)}"><span class="upm"><b>${lb}</b><small>${esc(x.sale_number)}${x.bill?" · jatuh tempo "+esc(x.bill.due||"-"):" · "+esc(x.date)}</small></span><span class="upa"><b>${rp(owedS(x))}</b>${f?`<small class="smw">+ denda ${rp(f)}</small>`:""}</span></label>`}).join("");
  cnb=db.water_connections.filter(c=>c.party_id===S.lkp).map(c=>`<button class="b s sm" onclick="mdOpen('wd','${c._id}')">Rincian sambungan ${esc(c.meter_no)}</button>`).join(""),
  pan=dcard("Tagihan "+esc(p.name||"pelanggan"),L.length?L.length+" belum lunas · dipilih "+sel.length:"Tidak ada tunggakan",(cnb?`<div class="fl">${cnb}</div>`:"")+(L.length?`<div class="fl"><button class="b s sm" onclick="lkAll(true)">Pilih semua</button><button class="b s sm" onclick="lkAll(false)">Kosongkan</button><button class="b s sm" onclick="lkClose()">Tutup</button></div><div class="upl">${rows}</div>`+(sel.length?`<div class="kvg"><div class="kv"><span class="k">Tagihan dipilih</span><b>${rp(sO)}</b></div>${sF?`<div class="kv"><span class="k">Denda</span><b>${rp(sF)}</b></div>`:""}<div class="kv"><span class="k">Total diterima</span><b>${rp(sO+sF)}</b></div></div>`:"")+(can?fld("lk-d","Tanggal bayar",{type:"date",value:d,a:' onchange="S.lkd=this.value;render()"'})+fld("lk-k","Kas/Bank",{t:"select",opts:opt(db.cash_accounts.filter(isAct),k=>[k._id,k.name])})+(sF?`<label class="ck"><input type="checkbox" id="lk-f0"> Bebaskan denda keterlambatan</label>`:"")+`<button class="b" ${sel.length?"":"disabled "}onclick="askC('loketBayar','')">Terima pembayaran${sel.length?" "+rp(sO+sF):""}</button>`:`<p class="k">Anda hanya dapat melihat data ini; menerima pembayaran membutuhkan izin kelola Pamsimas.</p>`):`<div class="empty em"><p>Semua tagihan pelanggan ini sudah lunas.</p></div>`),"alf")}
 const kw=(S.lkr||[]).map(i=>db.payments.find(y=>y._id===i)).filter(Boolean),
  hasil=kw.length?dcard("Pembayaran tercatat",kw.length+" kuitansi",`<div class="lda">${kw.map(y=>{const sx=db.sales.find(z=>z._id===y.sale_id)||{};return dkb("Kuitansi "+esc(sx.sale_number||"")+" · Rp "+fm(y.amount+(y.fine||0)),"openDoc('kuit','"+y._id+"')")}).join("")}</div>`,""):"";
 return`<h2>Loket Pembayaran</h2><p class="k">Cari pelanggan, pilih tagihan yang dibayar, lalu terima pembayaran sekaligus. Pembayaran sebagian dicatat lewat sub-tab Piutang.</p>${cari}${hasil}${pan}`}

// ===== v1.1.207: daftar kerja baca meter (cetak per rute) dan petugas per rute =====
const airRt=()=>db.settings.air_rute&&typeof db.settings.air_rute==="object"&&!Array.isArray(db.settings.air_rute)?db.settings.air_rute:{},
 rtOf=c=>String(c.rute||"").trim()||String(cust(c.party_id).address||"").trim()||"Tanpa alamat",
 dkAll=()=>db.water_connections.filter(c=>c.status==="aktif"&&(S.unit==="all"||c.unit_id===S.unit)),
 dkRoutes=()=>[...new Set(dkAll().map(rtOf))].sort((a,b)=>a.localeCompare(b,"id",{numeric:true})),
 dkSort=(a,b)=>{const u=c=>c.urut===undefined||c.urut===""||c.urut===null?1e9:+c.urut;return u(a)-u(b)||String(a.meter_no).localeCompare(String(b.meter_no),"id",{numeric:true})};
function dkData(per){const all=S.dkb==="semua",rs=dkRoutes(),f=S.dkf&&rs.includes(S.dkf)?S.dkf:"";
 return rs.filter(r=>!f||r===f).map(r=>{const cs=dkAll().filter(c=>rtOf(c)===r).sort(dkSort);return{r,pt:airRt()[r]||"",cs:cs.filter(c=>all||!billOf(c._id,per)),n:cs.length,done:cs.filter(c=>billOf(c._id,per)).length}}).filter(g=>g.cs.length)}
function rtSet(i,v){try{const r=dkRoutes()[+i];if(!r)return;v=String(v||"").trim().slice(0,60);const m=Object.assign({},airRt());if(v)m[r]=v;else delete m[r];db.settings.air_rute=m;audit("update","settings","air_rute",r+(v?" → "+v:" (petugas dihapus)"));save();S.msg="Petugas rute "+r+(v?": "+v:" dihapus")}catch(e){S.msg="⚠ "+e.message}render()}
function vDk(per){const bar=docBar(0),rs=dkRoutes(),G=dkData(per),can=!noPerm("air.kelola"),f=S.dkf&&rs.includes(S.dkf)?S.dkf:"";
 if(!rs.length)return`${bar}<p class="k">Belum ada sambungan aktif.</p>`;
 const all=rs.map(r=>{const cs=dkAll().filter(c=>rtOf(c)===r);return{r,n:cs.length,done:cs.filter(c=>billOf(c._id,per)).length}}),
  ctl=dcard("Daftar kerja baca meter "+esc(per),G.reduce((t,g)=>t+g.cs.length,0)+" sambungan di "+G.length+" rute",`<p class="k">Cetak daftar ini untuk dibawa petugas ke lapangan, isi angka meter di kertas, lalu input di Baca Meter. Rute diambil dari isian Rute di data sambungan (kosong = alamat pelanggan); urutan diatur lewat isian Urutan.</p><div class="fl"><select aria-label="Rute" onchange="S.dkf=this.value;render()"><option value="">Semua rute</option>${rs.map(r=>`<option value="${esc(r)}"${r===f?" selected":""}>${esc(r)}</option>`).join("")}</select><select aria-label="Isi daftar" onchange="S.dkb=this.value;render()"><option value="">Hanya yang belum ditagih</option><option value="semua"${S.dkb==="semua"?" selected":""}>Semua sambungan aktif</option></select></div><div class="upl">${all.map((a,i)=>`<div class="upr alr"><span class="upm"><b>${esc(a.r)}</b><small>${a.done} dari ${a.n} ditagih</small></span><span class="upa">${can?`<input aria-label="Petugas ${esc(a.r)}" placeholder="Petugas baca" maxlength="60" value="${esc(airRt()[a.r]||"")}" onchange="rtSet(${i},this.value)">`:`<b>${esc(airRt()[a.r]||"-")}</b>`}</span></div>`).join("")}</div>`,"");
 const sh=G.map(g=>`<div class="dkp"><div class="${dcl(0)}">${kop()}<h3>DAFTAR KERJA BACA METER</h3><div class="cn">Periode ${esc(per)} · Rute ${esc(g.r)}${g.pt?" · Petugas "+esc(g.pt):""}</div><div class="dkw">${tbl(["No","No. Meter","Nama","Alamat","#Angka bulan lalu","Angka bulan ini","Ket."],g.cs.map((c,i)=>{const p=cust(c.party_id);return`<tr><td>${i+1}</td><td>${esc(c.meter_no)}</td><td>${esc(p.name||"")}</td><td>${esc(p.address||"")}</td><td class="n">${qf(wPrev(c._id))}</td><td></td><td></td></tr>`}))}</div>${sig([["Petugas baca",g.pt]],0,today())}</div></div>`).join("");
 return`${bar}<div class="noprint">${ctl}</div>${sh||`<p class="k">Semua sambungan pada pilihan ini sudah ditagih untuk periode ${esc(per)}.</p>`}`}
